import{_ as e,o as t,c as r,a3 as p}from"./chunks/framework.D3kUw6rp.js";const _=JSON.parse('{"title":"你好，我叫刘雨欣","description":"","frontmatter":{},"headers":[],"relativePath":"girls/lyx/index.md","filePath":"girls/lyx/index.md"}'),o={name:"girls/lyx/index.md"};function i(l,a,n,s,d,c){return t(),r("div",null,[...a[0]||(a[0]=[p('<h1 id="你好-我叫刘雨欣" tabindex="-1">你好，我叫刘雨欣 <a class="header-anchor" href="#你好-我叫刘雨欣" aria-label="Permalink to &quot;你好，我叫刘雨欣&quot;">​</a></h1><p>2026 在一切都稳中向好的情况下，居然还是踩了狗屎了。</p><p>本来 2026 将会是一个完美的年份，我们提前还清了房子的商业贷款，公司也兑现了加薪的承诺，一切都如期进行。</p><p>这次意外的「踩狗屎」，让本来非常完美的一年变得如鲠在喉，像吃了苍蝇一样恶心。</p><p>于是我不得不把这段经历写出来，告诫自己也好，惩罚她人也好，总之，它值得被记录。也需要被记录！！</p><h2 id="初识" tabindex="-1">初识 <a class="header-anchor" href="#初识" aria-label="Permalink to &quot;初识&quot;">​</a></h2><p>6 月的时候我因为有个快递电话需要接，于是临时关闭了「勿扰模式」，导致让一通贷款推销的电话打了进来，这类电话以前接了很多，都是推销贷款的，所以才开的「勿扰模式」</p><h2 id="教训" tabindex="-1">教训 <a class="header-anchor" href="#教训" aria-label="Permalink to &quot;教训&quot;">​</a></h2><p>不要接近在水中挣扎的人，求生欲会让她不顾一切的抓住可以触碰的东西，试图借力上岸，而这个过程，她们是不会在乎把岸边的人拉下水的。</p><p>善良就是她人侵害你的资本。</p><p>「君子不立危墙之下」</p><h2 id="自我剖析" tabindex="-1">自我剖析 <a class="header-anchor" href="#自我剖析" aria-label="Permalink to &quot;自我剖析&quot;">​</a></h2><p>我生气的原因是因为最终没睡到，追根究底的剖析了一下：</p><p>不是因为很想睡，求而不得，所以生气。</p><p>而是因为，没有很想睡，但是对方求着你借钱，各种承诺可以陪睡，最终借款之后，立刻翻脸，才生气的。</p><p>我举个很贴切的例子：</p><blockquote><p>你路过一家饭店，本来没打算进去吃饭，但是门口的服务员非常热情的邀请，不断承诺不用等位，立刻上菜。 于是你心软，反正都要吃，就试试看呗。</p><p>等你进店之后，却告知需要等位，且刚才的热情劲也没了，你会不会生气的立刻甩脸就走？</p></blockquote>',17)])])}const u=e(o,[["render",i]]);export{_ as __pageData,u as default};
